import{_ as n,l as B,o as t,c as o,v as e,p as E,x as r,d as A,i as s,S as l}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Betting Against Beta 原文","description":"","frontmatter":{"title":"Betting Against Beta 原文","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/frazzini-bab.md","filePath":"quant/frazzini-bab.md","lastUpdated":1789023840000}'),h={name:"quant/frazzini-bab.md"};function p(d,a,c,_,m,b){const i=B("Mermaid");return t(),o("div",null,[a[1]||(a[1]=e('<h1 id="betting-against-beta-原文" tabindex="-1">Betting Against Beta 原文 <a class="header-anchor" href="#betting-against-beta-原文" aria-label="Permalink to &quot;Betting Against Beta 原文&quot;">​</a></h1><div class="epigraph"><p>受杠杆约束的投资者会超配高 β 资产，压平证券市场线；能用杠杆的投资者则应买入低 β、自行加杠杆，并把高 β 去杠杆后卖空。</p><footer>—— Frazzini &amp; Pedersen, Betting Against Beta, Journal of Financial Economics, 2014</footer></div><p><a href="/quant/low-vol-bab">低波动 / BAB</a> 一文把 BAB 与特异波动之谜拆开，并写出 β 估计与 \\(1/\\beta\\) 杠杆。本篇回到 2014 年原文：理论从 Black 的受限 CAPM 来，实证覆盖美股、国际股票、国债、信用与期货，状态变量是融资紧张程度。读这篇是为了复制论文的主张，而不是为了再写一遍「低波产品」。低波动指数没有把 β 调到 1，第一主成分仍是减市场；BAB 赌的是<strong>斜率</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAPM 说 \\(\\mathrm{E}[R_i]-R_f=\\beta_i\\bigl(\\mathrm{E}[R_M]-R_f\\bigr)\\)。若一部分投资者不能借贷或面临保证金上限，他们会用高 β 证券充当杠杆替代，把高 β 的当期价格抬高、预期收益压低。能加杠杆的投资者本应买低 β、借钱放大，但他们的资金同样有限。均衡不是证券市场线消失，而是变平：低 β 留下正 α，高 β 留下负 α。Black（1972）已经写出受限借款的 CAPM；Frazzini–Pedersen 要做的是把这条斜率不足写成可交易的多空，并在多类资产上检验。</p><p>需要回答三件事。第一，平的 SML 是不是只存在于美股小盘？第二，溢价在控制规模、价值、动量之后还在不在？第三，融资约束收紧时（TED 走阔、危机保证金上升），BAB 是否如机制所预测的那样更强——同时又会不会因为杠杆多头被强平而回撤？原文的结构就是理论、构造、跨资产表、再加融资状态。</p><h3 id="嵌入杠杆与「自己加杠杆」不是同一约束" tabindex="-1">嵌入杠杆与「自己加杠杆」不是同一约束 <a class="header-anchor" href="#嵌入杠杆与「自己加杠杆」不是同一约束" aria-label="Permalink to &quot;嵌入杠杆与「自己加杠杆」不是同一约束&quot;">​</a></h3><p>期货、期权、结构性产品本身带杠杆，受约束的投资者仍可能买高 β 的嵌入杠杆工具，而不是去期货市场按保证金最优配置。原文把国债期限、公司债评级、商品与股指期货也做成 BAB：在这些市场上，「β」是对当地市场因子的暴露（久期、信用利差、商品指数），约束叙事换成保证金与风险预算。若 BAB 只在个股上显著、在期货上消失，杠杆约束就很难当主机制。跨资产显著，是 2014 年论文相对 Ang 等人特异波动研究的增量。</p><p><span class="marginnote">TED 利差是原文用的融资代理，不是唯一合法的状态变量。政策利率接近零时 TED 压缩，账面 BAB 与可实现 BAB 的差距会改道到保证金与借券费。不要只回归 TED 就宣布机制已被「证明」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>个股 β 拆成相关与波动：波动用约一年日收益，相关用约五年、重叠三日对数收益，以减轻非同步交易；再向 1 收缩，权重 \\(w=0.6\\)，</p> \\[\\hat\\beta_i=w\\,\\hat\\rho_{iM}\\frac{\\hat\\sigma_i}{\\hat\\sigma_M}+(1-w)\\cdot 1. \\]<p>每个形成日按 \\(\\hat\\beta\\) 分成低组 L 与高组 H（价值加权），记组合 β 为 \\(\\beta_L,\\beta_H\\)，策略收益为</p> \\[r_{t+1}^{\\mathrm{BAB}}=\\frac{1}{\\beta_L}(r_{t+1}^L-r_f)-\\frac{1}{\\beta_H}(r_{t+1}^H-r_f). \\]<p>事前净 β 为零，两边都把超额收益放到 β=1 的尺度上。债券与期货上，用对基准的回归 β 做同样的加杠杆/去杠杆。检验回归包括 CAPM、<a href="/quant/ff3">三因子</a>、Carhart 四因子：主张是 BAB 的 α 不被 SMB、HML、WML 吸收。与<a href="/quant/qmj">质量</a>同时回归时，安全块会抢一部分解释，这是后文，不是 2014 年正文的义务。</p><h3 id="跨资产表要各自定义市场" tabindex="-1">跨资产表要各自定义市场 <a class="header-anchor" href="#跨资产表要各自定义市场" aria-label="Permalink to &quot;跨资产表要各自定义市场&quot;">​</a></h3><p>美股的市场是价值加权股票；国债的「市场」是债券指数或水平因子；信用是公司债指数；期货是该资产类的美元超额收益。把股指期货的 BAB 用股票 SMB 去解释，没有意义。原文的要点是：<strong>同一套杠杆约束故事，在不同 β 的定义下重复出现</strong>。复制必须按资产类重估 β、重做杠杆，而不是把股票 BAB 的权重搬到商品上。</p>',17)),(t(),E(l,null,{default:r(()=>[s(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20TH%5B%22%E5%8F%97%E9%99%90%20CAPM%EF%BC%9ASML%20%E5%8F%98%E5%B9%B3%22%5D%20--%3E%20EST%5B%22%E7%9F%AD%E7%AA%97%E6%B3%A2%E5%8A%A8%20%C3%97%20%E9%95%BF%E7%AA%97%E7%9B%B8%E5%85%B3%20%2B%20%E6%94%B6%E7%BC%A9%22%5D%0A%20%20EST%20--%3E%20LS%5B%22%E4%BD%8E%CE%B2%E5%8A%A0%E6%9D%A0%E6%9D%86%20%2F%20%E9%AB%98%CE%B2%E5%8E%BB%E6%9D%A0%E6%9D%86%22%5D%0A%20%20LS%20--%3E%20EQ%5B%22%E7%BE%8E%E8%82%A1%E4%B8%8E%E5%9B%BD%E9%99%85%E8%82%A1%E7%A5%A8%22%5D%0A%20%20LS%20--%3E%20FI%5B%22%E5%9B%BD%E5%80%BA%E4%B8%8E%E4%BF%A1%E7%94%A8%22%5D%0A%20%20LS%20--%3E%20FUT%5B%22%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20EQ%20--%3E%20ALPHA%5B%22%E7%9B%B8%E5%AF%B9%20FF3%20%2F%20Carhart%20%E7%9A%84%20%CE%B1%22%5D%0A%20%20FI%20--%3E%20ALPHA%0A%20%20FUT%20--%3E%20ALPHA%0A%20%20TED%5B%22%E8%9E%8D%E8%B5%84%E7%B4%A7%E5%BC%A0%20TED%22%5D%20--%3E%20ST%5B%22%E7%8A%B6%E6%80%81%EF%BC%9A%E5%9D%87%E5%80%BC%E6%9B%B4%E9%AB%98%E3%80%81%E5%9B%9E%E6%92%A4%E4%B9%9F%E5%8F%AF%E8%83%BD%E6%9B%B4%E5%A4%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>主叙事是资金约束。共同基金、部分保险与零售不能加杠杆，考核又相对基准，于是超配高 β；对冲基金可以加杠杆，但受保证金、VaR 与赎回限制，不能把 SML 完全扳直。约束越紧，低 β 越便宜、BAB 期望越高。危机里两条力对撞：事前期望上升，同时杠杆多头的融资被抽走，实现收益可以大负。因此机制预测的是<strong>平均</strong>为正、<strong>条件</strong>依赖，不是尾部保险。</p><p>行为补充是彩票偏好：投资者为高偏度、高波动支付过高价格。这条更贴近特异波动与低价股，原文并不靠它解释大盘与国债。代理问题：经理厌恶「借钱买公用事业」的跟踪误差，即使 CAPM α 为正。三条机制对交易的含义不同：资金约束怕融资利率与保证金；彩票怕散户风险偏好；代理怕基准与考核周期。</p><h3 id="事后-β-不等于事前杠杆" tabindex="-1">事后 β 不等于事前杠杆 <a class="header-anchor" href="#事后-β-不等于事前杠杆" aria-label="Permalink to &quot;事后 β 不等于事前杠杆&quot;">​</a></h3><p>收缩、重叠多日相关、滞后再平衡，都是为了减少「估高的 β 被做空、真实 β 没那么高」所制造的假市场空头。即使如此，实现净 β 常不为零。报告 2014 年策略必须同时给：平均收益、CAPM α、实现净 β、以及融资成本情景。只报未杠杆的低 β 组超额，那是低波产品，不是 BAB。只报假设零融资成本的杠杆多头，那是回测上界。</p><p><span class="marginnote">原文的 BAB 与后来的「对相关下注 / 对波动下注」分解不是同一篇文章。2014 年把 β 当整体排序键。若你把溢价全部归因于相关或全部归因于波动，需要另给出处，不要写进 Frazzini–Pedersen 2014 的定义里。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>杠杆成本随政策利率与信用利差变；空头借券在拥挤的高 β 成长股上可以贵到吃掉 α。<a href="/quant/qmj">QMJ</a> 的安全块与五因子的 RMW 会吸收一部分低 β α，剩余取决于样本与行业控制。行业中性 BAB 更接近「同一行业内的 β 斜率」，通常仍在但更薄。A 股融资融券标的与杠杆限制使空头腿弱于美股。</p><p>不要把最低波动十分位的等权收益叫做本文的 BAB。不要把期权隐含波动的低 IV 策略直接引用 2014 年。不要在已经杠杆到 β=1 之后还用 CAPM 的市场超额去「再解释」一遍净市场——净市场应接近零，显著的剩余才是题目。</p><p><span class="marginnote">真实出处：Frazzini &amp; Pedersen, <em>Betting Against Beta</em>, Journal of Financial Economics, 2014。理论前身是 Black, 1972。特异波动见 Ang, Hodrick, Xing &amp; Zhang, 2006，对比见<a href="/quant/low-vol-bab">低波动 / BAB</a>。证券市场线过平是更老的实证，不要写成 2014 年才发现。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>2014 年原文把受限杠杆下的平坦 SML 做成两边都调到 β=1 的多空。</li><li>β 用短窗波动、长窗相关并收缩；跨股票、债券、期货重复。</li><li>融资约束解释均值与状态，也解释危机回撤；彩票偏好更贴近特异波动。</li><li>必须报告实现净 β 与融资成本，不能把低波指数当成 BAB。</li><li>出处：Frazzini &amp; Pedersen, Journal of Financial Economics, 2014。</li></ul>',12))])}const g=n(h,[["render",p]]);export{u as __pageData,g as default};
